"""Export all static matplotlib figures generated by the current examples."""

from __future__ import annotations

import contextlib
import io
import os

os.environ.setdefault("MPLBACKEND", "Agg")

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt

from common import (
    FIGURE_MANIFEST_FIELDS,
    INDIVIDUAL_DIR,
    MANIFEST,
    figure_title,
    is_inside,
    iter_cases,
    run_case,
    slugify,
    write_manifest,
)


def _clear_existing_individual_pngs() -> None:
    INDIVIDUAL_DIR.mkdir(parents=True, exist_ok=True)
    for path in INDIVIDUAL_DIR.glob("*.png"):
        if not is_inside(path, INDIVIDUAL_DIR):
            raise RuntimeError(f"refusing to remove outside individual dir: {path}")
        path.unlink()


def main() -> int:
    _clear_existing_individual_pngs()
    records: list[dict[str, str]] = []
    active = {"case": None, "count": 0}
    original_show = plt.show

    def save_show(*args, **kwargs):
        case = active["case"]
        for fig_num in plt.get_fignums():
            fig = plt.figure(fig_num)
            active["count"] += 1
            figure_index = active["count"]
            title = figure_title(fig)
            filename = (
                f"{case.index:02d}_cell{case.cell_index}_"
                f"{slugify(case.title, 50)}_{figure_index:03d}_"
                f"{slugify(title, 70)}.png"
            )
            path = INDIVIDUAL_DIR / filename
            fig.savefig(path, dpi=180, bbox_inches="tight")
            records.append(
                {
                    "case_index": str(case.index),
                    "cell_index": str(case.cell_index),
                    "case_title": case.title,
                    "figure_index": str(figure_index),
                    "figure_title": title,
                    "path": str(path),
                }
            )
        plt.close("all")

    plt.show = save_show
    try:
        for case in iter_cases(haah_visual_split=True):
            active["case"] = case
            active["count"] = 0
            with contextlib.redirect_stdout(io.StringIO()):
                run_case(case, visualize=True)
    finally:
        plt.show = original_show
        plt.close("all")

    write_manifest(MANIFEST, records, FIGURE_MANIFEST_FIELDS)

    print(f"Saved {len(records)} figures to {INDIVIDUAL_DIR}")
    print(f"Manifest: {MANIFEST}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
